hadis=[('Günde yüz kez tövbe','فاني اتوب في اليوم اليه مايه مره','sitte','Ey insanlar! Allah’a tövbe edin; ben günde yüz kez O’na tövbe ediyorum (Müslim).'),('Çölde devesini bulan adam','لله اشد فرحا بتوبه عبده','sitte','Allah, kulunun tövbesine, çölde kaybettiği devesini bulan kimseden daha çok sevinir (Buhârî, Müslim).')],
amel=['Her gün en az yüz kez “Estağfirullah” de.','Hakkını yediğin birinden bugün helallik iste.','Yatmadan önce günün hatalarını düşün ve Allah’tan af dile.'],
muhasebe='Bugün tövbe etmem gereken bir söz, bakış veya davranışım oldu mu?',
