ayet=[('Hadîd 57:4','57-4','Nerede olursanız olun O sizinle beraberdir; Allah yaptıklarınızı görür.'),('Alak 96:14','96-14','O, Allah’ın gördüğünü bilmez mi?'),('Âl-i İmrân 3:5','3-5','Yerde ve gökte hiçbir şey Allah’a gizli kalmaz.')],
hadis=[('Cibrîl hadisi: ihsan','ان تعبد الله كانك تراه','sitte','Allah’ı görüyormuş gibi ibadet etmendir; sen O’nu görmesen de O seni görür (Müslim).'),('“Nerede olursan ol Allah’tan kork”','اتق الله حيثما كنت','tisa','Kötülüğün ardından bir iyilik yap ki onu silsin; insanlara güzel ahlakla davran (Tirmizî).')],
