hadis=[('Helal ve haram açıktır','الحلال بين والحرام بين','sitte','Şüpheliden sakınan dinini ve namusunu korumuş olur (Buhârî, Müslim).'),('“Takva buradadır”','التقوي ها هنا','sitte','Peygamber göğsüne üç kez işaret etti (Müslim).')],
